program.compute:
options = read('/input/options')
candidates = [r for r in options if 'alpha' in r['tags']]
result = []
for a in candidates:
    for b in options:
        if 'beta' in b['tags'] and a['id'] != b['id']:
            trial = [a['id'], b['id']]
            if valid(trial):
                result = trial
                break
    if result:
        break
if not result:
    for a in candidates:
        if 'beta' in a['tags']:
            trial = [a['id']]
            if valid(trial):
                result = trial
                break

program.effects:
if exists('/output/selection'):
    existing = read('/output/selection')
    if valid(existing):
        selection = existing
    else:
        selection = result
else:
    selection = result
    write('/output/selection', selection)
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

